34	export default function Scene(props: Props) {
35	  const frame = useCurrentFrame();
36	  const {fps, durationInFrames} = useVideoConfig();
37	  const theme = props.theme;
38	  const d = props.data;
39	  const fade = Math.min(ramp(frame, 0, 8), 1 - ramp(frame, durationInFrames - 14, 14));
40	  const W = 1680, NW = 252, NH = 110, GAP = (W - 6 * NW) / 5, RY = 70, CY = RY + NH / 2;
41	  const cx = (i: number) => i * (NW + GAP) + NW / 2;
42	  const D0 = 30, SPAN = 200;
43	  const tAt = (x: number) => D0 + (SPAN * (x - cx(0))) / (cx(5) - cx(0));
44	  const dotX = interpolate(frame, [D0, D0 + SPAN], [cx(0), cx(5)], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
45	  const nodeT = (i: number) => (i === 0 ? ramp(frame, 6, 20) : ramp(frame, tAt(cx(i) - NW / 2) - 22, 20));
46	  const nodeA = (i: number) => clamp01((dotX - (cx(i) - NW / 2)) / 30);
47	  const dotO = ramp(frame, D0 - 8, 8);
48	  const pulse = 0.5 + 0.5 * Math.sin(frame / 8);
49	  const c3 = cx(3), LY = 260, LH = 100, LC = LY + LH / 2;
50	  const stem = ramp(frame, 150, 22);
51	  const oX = c3 - 100, cX = c3 + 140, cW = 280, mX = cX + cW + 40;
52	  const c1 = ramp(frame, 188, 12), c2 = ramp(frame, 214, 12);
53	  const iX = c3 - 420, iW = 280;
54	  const bl = d.branch;
55	  return (
56	    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
57	      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
58	      <div style={{flex: 1, display: 'flex', alignItems: 'center'}}>
59	        <svg width={W} height={500} viewBox={`0 0 ${W} 500`}>
60	          <path d={`M${cx(5)},${RY} V28 H${cx(0)} V${RY}`} fill='none' stroke={theme.muted} strokeWidth={2} strokeDasharray='10 10' opacity={0.8 * ramp(frame, 250, 24)} />
61	          <Chevron x={cx(0)} y={RY - 4} dir='d' theme={theme} o={ramp(frame, 270, 10)} />
62	          <text x={W / 2} y={38} textAnchor='middle' fontSize={size(28, theme)} fill={theme.body} stroke={theme.background} strokeWidth={26} paintOrder='stroke' opacity={ramp(frame, 266, 20)}>{d.interrupt}</text>
63	          {d.nodes.map((n, i) => (
64	            <Box key={i} x={cx(i) - NW / 2} y={RY} w={NW} h={NH} label={n.label} mono={n.mono} t={nodeT(i)} active={nodeA(i)} theme={theme} fs={size(32, theme)} />
65	          ))}
66	          {d.nodes.slice(0, -1).map((n, i) => {
67	            const x1 = cx(i) + NW / 2, x2 = cx(i + 1) - NW / 2;
68	            const fr = clamp01((dotX - x1) / (x2 - x1));
69	            return (
70	              <g key={i}>
71	                <line x1={x1} y1={CY} x2={x2} y2={CY} stroke={theme.muted} strokeWidth={2} opacity={0.4 * nodeT(i + 1)} />
72	                <line x1={x1} y1={CY} x2={x1 + (x2 - x1) * fr} y2={CY} stroke={theme.accent} strokeWidth={3} />
73	                <Chevron x={x2} y={CY} dir='r' theme={theme} o={fr >= 1 ? 1 : 0} />
74	              </g>
75	            );
76	          })}
77	          <circle cx={dotX} cy={CY} r={22 + 4 * pulse} fill={theme.accent} opacity={0.22 * dotO} />
78	          <circle cx={dotX} cy={CY} r={9} fill={theme.accent} opacity={dotO} />
79	          <line x1={c3} y1={RY + NH} x2={c3} y2={RY + NH + (LY - RY - NH) * stem} stroke={theme.accent} strokeWidth={3} />
80	          <path d={`M${c3},220 H${iX + iW / 2} V${LY}`} fill='none' stroke={theme.muted} strokeWidth={2} strokeDasharray='8 8' opacity={ramp(frame, 176, 24)} />
81	          <Box x={iX} y={LY} w={iW} h={LH} label={d.optional} t={ramp(frame, 184, 22)} active={0} theme={theme} fs={size(28, theme)} dashed split />
82	          <Box x={oX} y={LY} w={200} h={LH} label={bl[0]} t={ramp(frame, 166, 20)} active={stem >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} />
83	          <line x1={oX + 200} y1={LC} x2={oX + 200 + 40 * c1} y2={LC} stroke={theme.accent} strokeWidth={3} />
84	          <Chevron x={oX + 240} y={LC} dir='r' theme={theme} o={c1 >= 1 ? 1 : 0} />
85	          <Box x={cX} y={LY} w={cW} h={LH} label={bl[1]} t={ramp(frame, 196, 20)} active={c1 >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} split />
86	          <line x1={cX + cW} y1={LC} x2={cX + cW + 40 * c2} y2={LC} stroke={theme.accent} strokeWidth={3} />
87	          <Chevron x={mX} y={LC} dir='r' theme={theme} o={c2 >= 1 ? 1 : 0} />
88	          <Box x={mX} y={LY} w={200} h={LH} label={bl[2]} t={ramp(frame, 224, 20)} active={c2 >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} />
89	          <text x={0} y={470} fontSize={size(30, theme)} fill={theme.muted} opacity={ramp(frame, 300, 24)}>{d.caption}</text>
90	        </svg>
91	      </div>
92	    </AbsoluteFill>
93	  );
94	}
