1	// Added by Jarvis (kit v1). Fixed text: read it, import it, do not edit it. Motion of the art direction as frames.
2	import {Easing, interpolate} from "remotion";
3	import type {CSSProperties} from "react";
4	
5	export type Theme = {
6	  background: string; text: string; accent: string; muted: string; body: string; surface: string;
7	  font_heading: string; font_body: string; heading_weight: number; body_weight: number;
8	  radius: number; gap: number; scale: number; enter_ms: number; stagger_ms: number; easing: string; transition: string;
9	};
10	
11	const CURVES: Record<string, (t: number) => number> = {
12	  linear: (t) => t,
13	  ease_out: Easing.out(Easing.cubic),
14	  ease_in_out: Easing.inOut(Easing.cubic),
15	  standard: Easing.bezier(0.2, 0, 0, 1),
16	  emphasized: Easing.bezier(0.3, 0, 0, 1.15),
17	  snappy: Easing.bezier(0.2, 0.9, 0.3, 1),
18	};
19	
20	// 0 -> 1 over the direction's enter time, shifted by its stagger for the n-th element (index 0, 1, 2...). Clamped on both sides.
21	export function progress(frame: number, fps: number, theme: Theme, index = 0): number {
22	  const start = (theme.stagger_ms * index / 1000) * fps;
23	  const length = Math.max(1, (theme.enter_ms / 1000) * fps);
24	  return interpolate(frame, [start, start + length], [0, 1], {
25	    extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: CURVES[theme.easing] ?? CURVES.ease_out,
26	  });
27	}
28	
29	// The direction's transition as a style for an element entering with progress p: fade, slide, scale or wipe (none: shown at once).
30	export function enterStyle(p: number, theme: Theme): CSSProperties {
31	  switch (theme.transition) {
32	    case "none": return {};
33	    case "slide": return {opacity: p, transform: `translateY(${(1 - p) * 32}px)`};
34	    case "scale": return {opacity: p, transform: `scale(${0.92 + 0.08 * p})`};
35	    case "wipe": return {clipPath: `inset(0 ${(1 - p) * 100}% 0 0)`};
36	    default: return {opacity: p};
37	  }
38	}
39	
40	// Sizes follow the direction's text scale and spacing: size(72) is a 72 px title at scale 1.
41	export function size(px: number, theme: Theme): number {
42	  return Math.round(px * theme.scale);
43	}
